// Bag clip living hinge, PETG, 0.4 nozzle, no supports.
// Two halves contacting at hinge mid-plane, open flat pose.
// Fold map 180 about pivot: F(x)=216-x, F(z)=10.4-z.

part = "arm_lower"; // [arm_lower, arm_upper, assembly]
cadverify_only = "";

Lbody = 100;
Wbody = 20;
Tbody = 3.2;
Hhalf = 8;
Thinge = 0.6;
Bgap = 2.0;

module instance(name, part, unit = 1) {
    echo(cadverify_instance = [name, part, unit]);
    if (cadverify_only == "" || cadverify_only == name) children();
}

module arm_lower() {
    cube([100, 20, 3.2], false);
    translate([99.9, 0, 0]) cube([8.1, 20, 0.6], false);
    translate([10, 1, 3.1]) cube([80, 1.5, 2.1], false);
    translate([10, 17.5, 3.1]) cube([80, 1.5, 2.1], false);
    translate([2, 5, 3.1]) cube([6, 10, 2.1], false);
    translate([7.9, 6, 4.7]) cube([2.1, 8, 0.5], false);
}

module arm_upper() {
    cube([8.1, 20, 0.6], false);
    translate([7.9, 0, 0]) cube([100.1, 20, 3.2], false);
    translate([100, 5, 3.1]) cube([6, 10, 3.1], false);
    translate([97.9, 6, 5.7]) cube([2.5, 8, 0.5], false);
    translate([107.9, 6, 0]) cube([8.1, 8, 3.2], false);
}

if (part == "arm_lower") {
    echo(cadverify_spec = [
        ["bounds", [[0, 0, 0], [108, 20, 5.2]]],
        ["bodies", 1],
        ["through_holes", 0],
        ["support_faces", [["bed", "-z", 1500]]],
        ["overhangs_allowed", [["latch lip", [[7.5, 5.5, 4.5], [10.5, 14.5, 5.5]]]]],
        ["copies", 1],
        ["details", [
            ["arm", "material", [[30, 8, 1.2], [70, 12, 2.0]], 1],
            ["arm_wall", "thickness", [50, 10, 10], [0, 0, -1], 3.2],
            ["hinge", "thickness", [104, 10, 5], [0, 0, -1], 0.6],
            ["rib", "material", [[30, 1.3, 3.8], [70, 2.2, 4.8]], 1],
            ["rib2", "material", [[30, 17.8, 3.8], [70, 18.7, 4.8]], 1],
            ["latch_tower", "material", [[3, 7, 3.8], [7, 13, 5.0]], 1],
            ["latch_lip", "material", [[8.3, 7, 4.8], [9.6, 13, 5.1]], 1],
            ["bag_slot", "void", [[30, 4, 3.8], [70, 16, 5.0]], 1]
        ]]
    ]);
    arm_lower();
} else if (part == "arm_upper") {
    echo(cadverify_spec = [
        ["bounds", [[0, 0, 0], [116, 20, 6.2]]],
        ["bodies", 1],
        ["through_holes", 0],
        ["support_faces", [["bed", "-z", 1500]]],
        ["overhangs_allowed", [["latch lip", [[97.5, 5.5, 5.5], [100.8, 14.5, 6.5]]]]],
        ["copies", 1],
        ["details", [
            ["arm", "material", [[30, 8, 1.2], [70, 12, 2.0]], 1],
            ["arm_wall", "thickness", [50, 10, 10], [0, 0, -1], 3.2],
            ["hinge", "thickness", [4, 10, 5], [0, 0, -1], 0.6],
            ["latch_tower", "material", [[101, 7, 4.0], [105, 13, 5.5]], 1],
            ["latch_lip", "material", [[98.3, 7, 5.8], [99.9, 13, 6.1]], 1],
            ["thumb_tab", "material", [[109, 7, 1.0], [114, 13, 2.2]], 1],
            ["field", "void", [[30, 4, 3.8], [70, 16, 5.0]], 1]
        ]]
    ]);
    arm_upper();
} else if (part == "assembly") {
    echo(cadverify_spec = [
        ["bounds", [[0, 0, 0], [224, 20, 6.2]]],
        ["support_faces", [["bed", "-z", 3000]]],
        ["motions", [
            ["close", ["upper"], "rotate", [108, 10, 5.2], [0, -1, 0], [0, 180],
                ["flex", [["upper", "lower", 1.0, "latch snap"]]],
                ["stops", [180]],
                ["rests", [0, 180]]
            ]
        ]],
        ["assembly_order", [
            [["lower"], [0, 0, 0]],
            [["upper"], [0, 0, -1]]
        ]]
    ]);
    instance("lower", "arm_lower") arm_lower();
    instance("upper", "arm_upper") translate([108, 0, 0]) arm_upper();
}
